import json, glob, sys, ast
sys.path.insert(0,'/workspace')
import pandas as pd
from verl.utils.reward_score import taco
tr = pd.read_parquet('/workspace/taco_verl/train.parquet')
def ptext(p):
    if isinstance(p,str):
        try: p=ast.literal_eval(p)
        except Exception: return p
    if isinstance(p,(list,tuple)) or hasattr(p,'tolist'):
        p=list(p)
        return p[0]['content']
    return str(p)
snip={}
for i,row in tr.iterrows():
    t=ptext(row['prompt'])
    q=t.split('QUESTION:')[-1].lstrip()[:100]
    snip[q]=row

checked=0; fullpass=0; fails=0; nonl_fails=0; nopair=0
samples=[]
files=sorted(glob.glob('/workspace/rollout_data/*.jsonl'), key=lambda p:int(p.split('/')[-1].split('.')[0]))
for f in files:
